const norm = t => ' ' + lower(t).replace(/[^a-z0-9؀-ۿ+#]+/g, ' ').trim() + ' ';
const hasAny = (text, kws) => { const n = norm(text); return kws.some(k => { const nk = norm(k); return nk.trim() && n.includes(nk); }); };
const decode = h => String(h || '').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&amp;/g, '&');
const strip = h => decode(h).replace(/<[^>]*>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/\s+/g, ' ').trim();
const safe = name => { try { return $(name).all().map(i => i.json).filter(j => j && !j.error); } catch (e) { return []; } };
const targets = list(S.target_keywords);
const excludes = list(S.exclude_keywords);
const locs = list(S.locations);
const regions = list(S.remote_regions);
const hours = Number(S.hours_window) || 24;
const now = Date.now();
const SKILLS = ['python','java','javascript','typescript','c++','c#','sql','linux','bash','powershell','networking','ccna','ccnp','tcp/ip','routing','switching','firewall','siem','splunk','qradar','wireshark','nmap','burp','owasp','penetration testing','incident response','soc','threat','vulnerability','iso 27001','security+','aws','azure','gcp','docker','kubernetes','terraform','ansible','ci/cd','git','react','node','node.js','express','django','flask','fastapi','rest api','n8n','zapier','make.com','automation','machine learning','deep learning','pytorch','tensorflow','scikit-learn','nlp','computer vision','llm','langchain','rag','prompt engineering','openai','agents','pandas','numpy','data analysis','power bi','excel','active directory','windows server','troubleshooting','itil','help desk','cloud','devops','mlops','statistics','communication','english'];
const parseSalary = t => {
  const s = String(t || '').replace(/,/g, '');
  if (!/\d/.test(s)) return {};
  const cur = /€|eur/i.test(s) ? 'EUR' : /£|gbp/i.test(s) ? 'GBP' : /egp|جنيه/i.test(s) ? 'EGP' : /\$|usd/i.test(s) ? 'USD' : '';
  const nums = (s.match(/\d+(?:\.\d+)?\s*k?/gi) || []).map(x => parseFloat(x) * (/k/i.test(x) ? 1000 : 1)).filter(n => n >= 100);
  if (!nums.length) return {};
  const period = /hour|hr\b|\/h\b/i.test(s) ? 'hour' : /month|\/mo|شهر/i.test(s) ? 'month' : 'year';
  const two = nums.slice(0, 2);
  return { min: Math.min(...two), max: Math.max(...two), cur, period };
};
const raw = [];
for (const r of safe('Fetch Remotive Jobs')) for (const j of (r.jobs || [])) raw.push({ source: 'remotive', id: j.id, title: j.title, company: j.company_name, location: j.candidate_required_location, work_mode: 'remote', salaryText: j.salary, posted: j.publication_date, url: j.url, desc: j.description, tags: j.tags });
for (const j of safe('Fetch RemoteOK Jobs')) if (j.id && j.position) raw.push({ source: 'remoteok', id: j.id, title: j.position, company: j.company, location: j.location || 'Remote', work_mode: 'remote', salary_min: Number(j.salary_min) || null, salary_max: Number(j.salary_max) || null, currency: (Number(j.salary_min) || Number(j.salary_max)) ? 'USD' : '', period: 'year', posted: j.date, url: j.apply_url || j.url, desc: j.description, tags: j.tags });
for (const r of safe('Fetch Arbeitnow Jobs')) for (const j of (r.data || [])) raw.push({ source: 'arbeitnow', id: j.slug, title: j.title, company: j.company_name, location: j.location, work_mode: j.remote ? 'remote' : 'onsite', posted: j.created_at ? j.created_at * 1000 : null, url: j.url, desc: j.description, tags: j.tags });
for (const j of safe('Fetch WeWorkRemotely RSS')) if (j.title && j.link) { const parts = String(j.title).split(': '); raw.push({ source: 'weworkremotely', id: j.guid || j.link, title: parts.length > 1 ? parts.slice(1).join(': ') : j.title, company: parts.length > 1 ? parts[0] : '', location: 'Remote', work_mode: 'remote', posted: j.isoDate || j.pubDate, url: j.link, desc: j.content || j.contentSnippet }); }
for (const r of safe('Fetch Company Boards')) {
  if (Array.isArray(r.jobs)) { for (const j of r.jobs) { const ln = (j.location && j.location.name) || ''; raw.push({ source: 'greenhouse', id: j.id, title: j.title, company: j.company_name || '', location: ln, work_mode: /remote/i.test(ln) ? 'remote' : 'onsite', posted: j.first_published || j.updated_at, url: j.absolute_url, desc: j.content }); } }
  else if (r.hostedUrl) { raw.push({ source: 'lever', id: r.id, title: r.text, company: String(r.hostedUrl).split('/')[3] || '', location: r.categories && r.categories.location, work_mode: r.workplaceType || '', posted: r.createdAt, url: r.applyUrl || r.hostedUrl, desc: (r.descriptionPlain || '') + ' ' + (r.additionalPlain || '') + ' ' + JSON.stringify(r.lists || []) }); }
}
for (const j of safe('Read Custom RSS Feeds')) if (j.title && j.link) raw.push({ source: 'rss', id: j.guid || j.link, title: j.title, company: j.creator || '', location: '', work_mode: '', posted: j.isoDate || j.pubDate, url: j.link, desc: j.content || j.contentSnippet });
const seenKey = new Set();
const seenDedup = new Set();
const out = [];
for (const j of raw) {
  if (!j.title || !j.url) continue;
  if (j.expired === true) continue;
  const title = strip(j.title);
  if (!hasAny(title, targets) || hasAny(title, excludes)) continue;
  const location = strip(j.location || '');
  const remote = j.work_mode === 'remote' || /remote|anywhere|worldwide|عن بعد/i.test(location);
  const inLoc = hasAny(location, locs);
  const remoteOk = remote && S.remote_ok !== false && (!location || /^remote$/i.test(location) || hasAny(location, regions));
  if (!inLoc && !remoteOk) continue;
  const pv = (typeof j.posted === 'string' && /^\d+$/.test(j.posted)) ? Number(j.posted) : j.posted;
  const t = pv ? new Date(pv).getTime() : NaN;
  if (!isFinite(t)) continue;
  const ageH = (now - t) / 3600000;
  if (ageH > 24 * 30 || ageH < -48) continue;
  const desc = strip(j.desc).slice(0, 3500);
  const key = (j.source + ':' + String(j.id || j.url)).toLowerCase().slice(0, 250);
  const dkey = (norm(title).trim() + '|' + norm(j.company).trim()).slice(0, 250);
  if (seenKey.has(key) || seenDedup.has(dkey)) continue;
  seenKey.add(key);
  seenDedup.add(dkey);
  let sal = { min: j.salary_min || null, max: j.salary_max || null, cur: j.currency || '', period: j.period || '' };
  if (!sal.min && !sal.max) { const p = parseSalary(j.salaryText); if (p.min) sal = p; }
  const hay = norm(title + ' ' + desc + ' ' + (Array.isArray(j.tags) ? j.tags.join(' ') : ''));
  const skills = SKILLS.filter(k => hay.includes(norm(k)));
  const emails = (desc.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi) || []).filter(e => !/no-?reply|privacy|example|abuse|unsubscribe|gdpr|dpo@|support@/i.test(e));
  const applyEmail = (emails.length && /(send|email|apply|cv|resume|قدم|أرسل|ارسل)/i.test(desc)) ? emails[0].toLowerCase() : '';
  const rank = targets.filter(k => hay.includes(norm(k))).length;
  const mode = remote ? 'remote' : (/hybrid/i.test(location + ' ' + (j.work_mode || '')) ? 'hybrid' : (j.work_mode || 'onsite'));
  out.push({ json: { job_key: key, dedup_key: dkey, source: j.source, title: title.slice(0, 200), company: strip(j.company).slice(0, 150), location: location.slice(0, 150) || (remote ? 'Remote' : ''), work_mode: String(mode).toLowerCase(), salary_min: sal.min, salary_max: sal.max, salary_currency: sal.cur || '', salary_period: (sal.min || sal.max) ? sal.period : '', posted_at: new Date(t).toISOString(), apply_url: j.url, apply_email: applyEmail, skills: skills.join(', '), is_fresh: ageH <= hours, description: desc, rank, fetched_total: raw.length } });
}
return out;

const S = $('Load Settings').first().json;
if (!String(S.cv_text || '').trim()) { throw new Error('cv_text is empty in jh_settings - paste your CV text first so scoring is based on your real CV.'); }
const lower = v => String(v == null ? '' : v).toLowerCase();
const targets = String(S.target_keywords || '').split(',').map(x => x.trim().toLowerCase()).filter(Boolean);
const seen = new Set();
const out = [];
for (const i of $input.all()) {
  const r = i.json || {};
  if (!r.id || !r.description) continue;
  if (r.status !== 'pending_score' && r.status !== 'score_failed') continue;
  const k = r.job_key || r.dedup_key;
  if (seen.has(k)) continue;
  seen.add(k);
  const hay = lower(r.title + ' ' + r.description);
  const rank = targets.filter(t => hay.includes(t)).length;
  out.push({ json: Object.assign({}, r, { row_id: r.id, rank }) });
}
out.sort((a, b) => b.json.rank - a.json.rank);
return out.slice(0, 40);

