const S = $('Load Settings').first().json;
const jobs = $('Prepare Jobs For Scoring').all();
const res = $input.all();
const maxApps = Number(S.max_daily_applications) || 5;
const th = Number(S.auto_apply_threshold) || 80;
const already = $('Count Today Applications').all().filter(i => i.json && i.json.id).length;
let quota = Math.max(0, maxApps - already);
const enabled = S.auto_apply_enabled === true;
const hasCv = !!String(S.cv_pdf_url || '').trim();
const minSal = Number(S.min_salary) || 0;
const salaryOk = j => {
  if (!minSal || (!j.salary_min && !j.salary_max)) return true;
  if (String(j.salary_currency).toUpperCase() !== String(S.min_salary_currency || '').toUpperCase() || j.salary_period !== S.min_salary_period) return true;
  return (Number(j.salary_max) || Number(j.salary_min)) >= minSal;
};
const merged = jobs.map((j, i) => {
  const o = (res[i] && res[i].json && res[i].json.output) || {};
  const scored = o.score !== undefined && o.score !== null;
  return Object.assign({}, j.json, { score: scored ? Math.max(0, Math.min(100, Math.round(Number(o.score) || 0))) : 0, reason: scored ? String(o.reason_ar || '').slice(0, 300) : 'تعذّر التقييم الآلي لهذه الوظيفة', meets_level: o.meets_level !== false, scored });
});
merged.sort((a, b) => b.score - a.score);
return merged.map(j => {
  let action = 'none';
  let status = j.scored ? 'scored' : 'score_failed';
  let note = '';
  const salOk = salaryOk(j);
  if (!salOk) note = 'الراتب المعلن أقل من الحد الأدنى';
  if (j.score >= th && j.meets_level && salOk) {
    action = 'manual';
    status = 'needs_manual';
    if (!j.apply_email) note = 'التقديم من موقع الجهة (نموذج أو تسجيل دخول)';
    else if (!enabled) note = 'ابعت الـCV بالإيميل على ' + j.apply_email;
    else if (!hasCv) note = 'رابط ملف الـCV (cv_pdf_url) غير مضبوط';
    else if (quota <= 0) note = 'تم الوصول للحد اليومي للطلبات';
    else { action = 'auto_apply'; status = 'applying'; quota -= 1; }
  }
  return { json: Object.assign({}, j, { action, status, status_note: note }) };
});

