const pending = safe('Get Awaiting Confirmation').filter(j => j.id && j.gmail_thread_id);
const msgs = safe('Check Outlook Replies');
const out = [];
for (const p of pending) {
  const replies = msgs.filter(m => m.conversationId === p.gmail_thread_id && lower(m.from && m.from.emailAddress && m.from.emailAddress.address) !== me);
  if (!replies.length) continue;
  const bounce = replies.find(m => /mailer-daemon|postmaster|undeliverable|delivery has failed|delivery status notification|لم يتم التسليم/i.test(lower(m.from && m.from.emailAddress && m.from.emailAddress.address) + ' ' + (m.subject || '')));
  if (bounce) { out.push({ json: { row_id: p.id, status: 'needs_manual', status_note: 'إيميل التقديم رجع (Bounce)، قدّم يدويًا من الرابط', confirmation_ref: '', confirmed_at: new Date().toISOString() } }); continue; }
  replies.sort((a, b) => new Date(a.receivedDateTime) - new Date(b.receivedDateTime));
  const r = replies[0];
  const text = (r.subject || '') + ' ' + (r.bodyPreview || '');
  const m = text.match(/(?:reference|ref\.?|application (?:id|number|no\.?)|confirmation (?:number|no\.?)|رقم (?:الطلب|المرجع))\s*[:#]?\s*([A-Z0-9][A-Z0-9-]{3,})/i);
  out.push({ json: { row_id: p.id, status: 'applied_confirmed', status_note: 'وصل رد من الجهة: ' + String(r.subject || '').slice(0, 150), confirmation_ref: m ? m[1] : '', confirmed_at: r.receivedDateTime || new Date().toISOString() } });
}
return out;

const S = $('Load Settings (Report)').first().json;
const safe = name => { try { return $(name).all().map(i => i.json).filter(j => j && !j.error); } catch (e) { return []; } };
const now = Date.now();
const H = 3600000;
const within = (d, h) => { const t = d ? new Date(d).getTime() : NaN; return isFinite(t) && (now - t) <= h * H; };
const one = s => String(s == null ? '' : s).replace(/[\r\n\t]+/g, ' ').replace(/ {4,}/g, '   ').trim();
