const seenRows = new Set();
const rows = safe('Get Jobs Last 30 Days').filter(r => r.id && r.source !== 'test').filter(r => { const k = r.job_key || r.dedup_key || r.id; if (seenRows.has(k)) return false; seenRows.add(k); return true; });
