const counts = {};
rows.forEach(r => String(r.skills || '').split(',').map(x => x.trim()).filter(Boolean).forEach(k => { counts[k] = (counts[k] || 0) + 1; }));
const topSkills = Object.entries(counts).sort((a, b) => b[1] - a[1]).slice(0, 8);
const skillsLine = rows.length < 10 ? 'بيانات غير كافية (' + rows.length + ' إعلان فقط في آخر 30 يوم)' : topSkills.map(e => e[0] + ' (' + e[1] + ')').join('، ') + ' — من ' + rows.length + ' إعلان';
const per = { year: 'سنويًا', month: 'شهريًا', hour: 'بالساعة' };
const groups = {};
rows.filter(r => (Number(r.salary_min) || Number(r.salary_max)) && r.salary_currency && r.salary_period).forEach(r => {
  const lo = Number(r.salary_min) || Number(r.salary_max);
  const hi = Number(r.salary_max) || lo;
  const k = r.salary_currency + '|' + r.salary_period;
  if (!groups[k]) groups[k] = { cur: r.salary_currency, period: r.salary_period, vals: [], src: new Set() };
  groups[k].vals.push((lo + hi) / 2);
  groups[k].src.add(r.source);
});
const MIN_N = 5;
const glist = Object.values(groups).sort((a, b) => b.vals.length - a.vals.length);
const salParts = glist.filter(g => g.vals.length >= MIN_N).map(g => 'متوسط ' + Math.round(g.vals.reduce((a, b) => a + b, 0) / g.vals.length).toLocaleString('en-US') + ' ' + g.cur + ' ' + (per[g.period] || g.period) + ' (من ' + g.vals.length + ' إعلان؛ المصادر: ' + Array.from(g.src).join('/') + ')');
const withSalary = glist.reduce((a, g) => a + g.vals.length, 0);
const salaryLine = salParts.length ? salParts.slice(0, 2).join(' | ') : 'بيانات غير كافية: ' + withSalary + ' إعلان فقط ذكر راتب في آخر 30 يوم (لازم ' + MIN_N + ' على الأقل بنفس العملة والفترة)';
