manual.slice(0, 10).forEach(r => L.push('- ' + r.title + ' – ' + (r.company || '') + ' (' + r.match_score + '%) | ' + (r.status_note || '') + (r.skill_gaps ? ' | ناقصك: ' + r.skill_gaps : '') + ' | ' + r.apply_url));
