const r = $input.first().json;
const one = s => String(s == null ? '' : s).replace(/[\r\n\t]+/g, ' ').replace(/ {2,}/g, ' ').trim();
const cut = (s, n) => { const x = one(s); return x.length > n ? x.slice(0, n - 1) + '…' : x; };
const short = s => one(s).startsWith('بيانات غير كافية') ? 'بيانات غير كافية لسه' : s;
const news = one(r.p7).split(' | ').slice(0, 2).map(x => cut(x, 45)).join(' | ');
return [{ json: Object.assign({}, r, { p1: cut(r.p1, 12), p2: cut(r.p2, 220), p3: cut(r.p3, 60), p4: cut(r.p4, 180), p5: cut(short(r.p5), 100), p6: cut(short(r.p6), 100), p7: cut(news, 95) }) }];

// Pairs each CareerMind reply with the job it was asked about and keeps the
// missing skills. A failed call (no score in the reply) is skipped, so the
// job keeps its Gemini score and the report simply shows no gaps for it.
const jobs = $('Deep Check?').all();
const out = [];
$input.all().forEach((item, i) => {
  const r = item.json || {};
  const job = jobs[i] && jobs[i].json;
  if (!job || !job.row_id || typeof r.job_match_score !== 'number') return;
  const gaps = [].concat(r.missing_skills || [], r.partial_match_skills || []).map(String).filter(Boolean);
  out.push({ json: { row_id: job.row_id, careermind_score: r.job_match_score, skill_gaps: gaps.slice(0, 8).join(', ').slice(0, 300) } });
});
return out;
